<?php
namespace App\Http\Controllers; use App\Domain\Clients\{ClientIndexViewData,ClientRegistry,ClientViewData}; use App\Models\Industry; use Illuminate\Contracts\View\View; use Illuminate\Http\Request; class PublicClientController extends Controller { public function index(Request $request,ClientIndexViewData $data):View{$type=in_array($request->string('type')->toString(),ClientRegistry::TYPES,true)?$request->string('type')->toString():null;$industry=$request->integer('industry')?:null;return view('clients.index',['clients'=>$data->get(max(1,$request->integer('page',1)),$type,$industry),'types'=>ClientRegistry::TYPES,'industries'=>Industry::publiclyVisible()->orderBy('title')->get(['id','title'])]+app(PublicSiteController::class)->sharedViewData($request));} public function show(Request $request,string $client,ClientViewData $data):View{$item=$data->published($client);if(!$item)abort(404);return view('clients.show',['client'=>$item,'preview'=>false]+app(PublicSiteController::class)->sharedViewData($request));} }
